import os
import sys


class Predictor:
    """KServe python predictor that serves the provided trigram scorer."""

    def __init__(self):
        # The registered model artifact (which includes scorer.py) is
        # downloaded to the directory in ARTIFACT_FILES_PATH on the serving pod.
        artifact_path = (
            os.environ.get("ARTIFACT_FILES_PATH")
            or os.environ.get("MODEL_FILES_PATH")
            or os.path.dirname(os.path.abspath(__file__))
        )
        if artifact_path not in sys.path:
            sys.path.insert(0, artifact_path)
        import scorer

        self._score = scorer.score

    def predict(self, inputs):
        # Accept either the raw list of texts or a KServe-style request body
        # {"instances": [...]}. Return one score float per input, in order.
        if isinstance(inputs, dict) and "instances" in inputs:
            items = inputs["instances"]
        else:
            items = inputs
        if not isinstance(items, list):
            items = [items]
        return [self._score(text)["score"] for text in items]

